def restore_water_batch_text(path,source):
    if str(path)!="src/data/wild_encounters.json":return source
    for key,original in ORIGINAL_WATER.items():
        label,method=key.split("|")
        start=source.index('"'+method+'": {',source.index('"base_label": "'+label+'"'))
        current=BALANCED_WATER[key]
        assert source[start:start+len(current)]==current,key
        source=source[:start]+original+source[start+len(current):]
    return source

def prior_water_batch_source(path):
    return restore_water_batch_text(path,prior_safari_land_source(path).decode("utf-8")).encode("utf-8")

def restore_prior_water_batch_text(path,source):
    return restore_water_batch_text(path,restore_prior_safari_land_text(path,source))
